(function(){
  var $=function(id){return document.getElementById(id)};
  function key(s){
    var m=$('mode').value;
    if(m==='ci') return s.toLowerCase();
    if(m==='trim') return s.trim();
    if(m==='both') return s.trim().toLowerCase();
    return s;
  }
  function run(){
    var raw=$('in').value;
    var lines=raw.length ? raw.split(/\r?\n/) : [];
    // a trailing newline should not count as an empty item
    if(lines.length && lines[lines.length-1]==='') lines.pop();
    var seen=Object.create(null), order=[], count=Object.create(null);
    lines.forEach(function(l){
      var k=key(l);
      if(!(k in seen)){ seen[k]=l; order.push(k); count[k]=1; }
      else count[k]++;
    });
    var keep=$('keep').value, out=order;
    if(keep==='only') out=order.filter(function(k){return count[k]===1});
    if(keep==='dupes') out=order.filter(function(k){return count[k]>1});
    if($('sort').checked) out=out.slice().sort(function(a,b){
      return String(seen[a]).localeCompare(String(seen[b]),undefined,{numeric:true,sensitivity:'base'});
    });
    var showCounts=$('counts').checked;
    var text=out.map(function(k){
      return showCounts ? seen[k]+'\t'+count[k] : seen[k];
    }).join('\n');
    $('nin').textContent=lines.length;
    $('nout').textContent=out.length;
    $('ndel').textContent=Math.max(0,lines.length-out.length);
    $('out').textContent=text||'The result appears here';
    var dupeCount=order.filter(function(k){return count[k]>1}).length;
    $('note').textContent = lines.length
      ? (dupeCount ? dupeCount+' value'+(dupeCount>1?'s appear':' appears')+' more than once.' : 'Every line is unique.')
      : '';
    if(window.WT) WT.resize();
  }
  ['in','mode','keep','sort','counts'].forEach(function(id){
    $(id).addEventListener('input',run); $(id).addEventListener('change',run);
  });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('out').textContent);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy result'},1400);
  });
  $('dl').addEventListener('click',function(){
    var b=new Blob([$('out').textContent],{type:'text/plain;charset=utf-8'});
    var u=URL.createObjectURL(b),a=document.createElement('a');
    a.href=u;a.download='deduplicated.txt';document.body.appendChild(a);a.click();
    setTimeout(function(){URL.revokeObjectURL(u);a.remove()},4000);
  });
  $('clear').addEventListener('click',function(){$('in').value='';run()});
  run();
})();
